int main() {
    int f[2], i, j;
    char r[5], a[5];

    while (true) {
        if (scanf("%4s %4s", r, a) != 2 || (r[0] == '0' && a[0] == '0')) break;
        for (f[0] = f[1] = 0, i = 0; i < 4; i++) 
            for (j = 0; j < 4; j++) 
                if (a[i] == r[j]) f[i != j]++;
        printf("%d %d\n", f[0], f[1]);
    }
}

#include <cstdio>
#include <cstring>

int main() {
    int f[2];
    char r[5], a[5];

    while (scanf("%4s %4s", r, a) == 2 && (r[0] != '0' || a[0] != '0')) {
        f[0] = f[1] = 0;
        int rCount[256] = {0}; // Create a frequency array for characters in r

        // Count occurrences of characters in r
        for (int j = 0; j < 4; j++) {
            rCount[r[j]]++;
        }

        // Compare characters in a with the frequency of characters in r
        for (int i = 0; i < 4; i++) {
            if (rCount[a[i]] > 0) {
                f[i != strchr(r, a[i]) - r]++;
            }
        }
        printf("%d %d\n", f[0], f[1]);
    }
}

#include <iostream>
#include <array>

int main() {
    std::array<int, 2> f;
    std::string r, a;

    while (std::cin >> r >> a, r != "0" && a != "0") {
        f.fill(0); // Reset f elements
        for (int i = 0; i < 4; i++) {
            // Instead of j from 4 down to 0, we use a single loop with a temporary counter
            for (int j = 0; j < 4; j++) {
                if (a[i] == r[j]) {
                    f[i != j]++; // Increment the appropriate index based on match condition
                }
            }
        }
        std::cout << f[0] << " " << f[1] << "\n";
    }
}

#include <cstdio>
#include <cstring>

int main() {
    int f[2];
    char r[5], a[5];

    while (scanf("%4s %4s", r, a) == 2 && (r[0] != '0' || a[0] != '0')) {
        int count[256] = {0}; // Array to count occurrences of characters in r
        for (int j = 0; j < 4; j++) {
            count[r[j]]++; // Count characters in r
        }

        f[0] = f[1] = 0; // Reset f array
        for (int i = 0; i < 4; i++) {
            if (count[a[i]] > 0) {
                if (r[i] == a[i]) {
                    f[0]++; // Correct position
                } else {
                    f[1]++; // Wrong position
                }
                count[a[i]]--; // Decrease count as it's been matched
            }
        }
        printf("%d %d\n", f[0], f[1]);
    }
}

