    int f[2];
    char r[5], a[5];

    while (true) {
        if (scanf("%4s %4s", r, a) != 2 || (r[0] == '0' && a[0] == '0')) break;
        f[0] = f[1] = 0;

        // Use a frequency array to count characters
        int count[256] = {0}; // Assuming ASCII characters
        for (int i = 0; i < 4; i++) {
            count[r[i]]++;
        }

        for (int i = 0; i < 4; i++) {
            if (count[a[i]] > 0) {
                f[i != strchr(r, a[i]) - r]++;
                count[a[i]]--; // Decrease count to avoid double counting
            }
        }

        printf("%d %d\n", f[0], f[1]);
    }
}
